#!/bin/bash
#
# Functions to manage code blocks automatically generated by dotfiles manager scripts. It should not be used by other scripts than the ones
# inside the '../<package_name>/scripts.stow/' folders.

__code_block_separator=DOTFILES_CODE_BLOCK_SEPARATOR

# Remove a code block from a file.
#
# $1: target file. Where to remove the code block.
code_block_remove() {
	local target_file="$1"

	local new_target_file=$(mktemp)

	# Appends the target file to the new one. Removes any existing code block
	cat "$target_file" | sed -z "s/\# $__code_block_separator\n.*\# $__code_block_separator\n//" >> "$new_target_file"

	# Overrides the last target file by the new one and removes the temporary target file
	cat "$new_target_file" > "$target_file"
	rm "$new_target_file"
}

# Add a code block between that sources a shell script.
# This code is between two unique indicators that works as delimiters. If called multiple times, the code beteen this delimiters is removed
# to ensure only one code block exists.
#
# $1: target file. Where to add the code block.
# $2: source file. The source command will source this file.
code_block_add_source() {
	local target_file="$1"
	local source_file="$2"

	local new_target_file=$(mktemp)

	# Adds the source command between the code block
	cat <<-EOF > "$new_target_file"
		# ${__code_block_separator}
		source $source_file
		# ${__code_block_separator}
	EOF

	# Appends the target file to the new one. Removes any existing code block
	cat "$target_file" | sed -z "s/\# $__code_block_separator\n.*\# $__code_block_separator\n//" >> "$new_target_file"

	# Overrides the last target file by the new one and removes the temporary target file
	cat "$new_target_file" > "$target_file"
	rm "$new_target_file"
}
